import time, csv, logging
from Adafruit_ADS1x15 import ADS1x15

ADS1115 = ADS1x15(0x0220)

def read_voltage():
    # This function reads the voltage from the Li-ion cell via ADC ADS1115.
    try:
        voltage = ADS1115.readADC_SingleEnded(0)
    except Exception as e:
        logging.error(f"Failed to read voltage: {str(e)}")
        return None
    return voltage

def calculate_soc(voltage):
    # This function calculates the state of charge (SOC) with an approximation curve.
    try:
        soc = ((voltage - 3.6) / 0.1) * 100 if voltage >= 3.6 else 0
    except Exception as e:
        logging.error(f"Failed to calculate SOC: {str(e)}")
        return None
    return soc

def control_led(soc):
    # This function controls the LED based on the state of charge (SOC).
    try:
        if soc > 50:
            print("LED is turning Green as battery is fully charged.")
            return "green"
        elif 20 <= soc <= 50:
            print("LED is turning Yellow as battery is halfway charged.")
            return "yellow"
        else: # when soc < 20
            print("LED is turning Red as battery needs charging.")
            return "red"
    except Exception as e:
        logging.error(f"Failed to control LED: {str(e)}")
        return None

def log_data(voltage, soc, led_color):
    # This function logs all data (voltage, SOC, and LED color) with timestamp into a CSV file.
    try:
        with open('battery_log.csv', mode='a') as battery_log:
            writer = csv.writer(battery_log, delimiter=',')
            now = time.ctime()
            writer.writerow([now, voltage, soc, led_color])
    except Exception as e:
        logging.error(f"Failed to log data: {str(e)}")

def main():
    while True:
        voltage = read_voltage()
        if voltage is None:
            break

        soc = calculate_soc(voltage)
        if soc is None:
            break

        led_color = control_led(soc)
        if led_color not in ['green', 'yellow', 'red']:
            break

        log_data(voltage, soc, led_color)

main()
